    37→  --color-q2:            #60a5fa;
    38→  --color-q2-bg:         rgba(96, 165, 250, 0.15);
    39→  --color-thesis:        #c084fc;
    40→  --color-thesis-bg:     rgba(192, 132, 252, 0.15);
    41→  --color-conf:          #f0a500;
    42→  --color-conf-bg:       rgba(240, 165, 0, 0.15);
    43→  --color-preprint:      #f87171;
