    87→
    88→/* ---------- Fonts ---------- */
    89→:root {
    90→  --font-display: 'Playfair Display', Georgia, 'Times New Roman', serif;
    91→  --font-sans:    'Source Sans 3', 'Helvetica Neue', system-ui, sans-serif;
    92→  --font-mono:    'JetBrains Mono', 'Fira Code', Consolas, monospace;
    93→
    94→  --radius-xs:   4px;
    95→  --radius-sm:   8px;
    96→  --radius-md:   14px;
    97→  --radius-lg:   22px;
    98→  --radius-xl:   32px;
    99→  --radius-full: 9999px;
   100→
   101→  --shadow-sm:  0 2px 8px rgba(0,0,0,0.12);
   102→  --shadow-md:  0 8px 32px rgba(0,0,0,0.18), 0 2px 8px rgba(0,0,0,0.12);
   103→  --shadow-lg:  0 20px 60px rgba(0,0,0,0.28), 0 6px 20px rgba(0,0,0,0.16);
   104→  --shadow-glow: 0 0 40px rgba(0, 200, 180, 0.18);
   105→
   106→  --transition: 0.22s ease;
   107→  --transition-slow: 0.4s ease;
   108→}
   109→
   110→[data-theme="light"] {
   111→  --shadow-sm:  0 2px 8px rgba(0,0,0,0.06);
   112→  --shadow-md:  0 8px 32px rgba(0,0,0,0.10), 0 2px 8px rgba(0,0,0,0.06);
   113→  --shadow-lg:  0 20px 60px rgba(0,0,0,0.12), 0 6px 20px rgba(0,0,0,0.08);
   114→  --shadow-glow: 0 0 40px rgba(0, 125, 114, 0.15);
   115→}
   116→
   117→/* ---------- Reset & Base ---------- */
   118→*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
   119→
   120→html {
   121→  scroll-behavior: smooth;
   122→  font-size: 16px;
   123→  -webkit-text-size-adjust: 100%;
   124→}
   125→
   126→body {
   127→  font-family: var(--font-sans);
   128→  color: var(--color-text);
   129→  background: var(--color-bg);
   130→  line-height: 1.7;
   131→  -webkit-font-smoothing: antialiased;
   132→  -moz-osx-font-smoothing: grayscale;
   133→  transition: background var(--transition-slow), color var(--transition-slow);
   134→  overflow-x: hidden;
   135→}
   136→
   137→img { max-width: 100%; display: block; }
   138→a  { color: var(--color-primary); text-decoration: none; }
   139→a:hover { text-decoration: underline; }
   140→button { cursor: pointer; font-family: var(--font-sans); }
   141→
   142→/* ---------- Scroll Progress Bar ---------- */
   143→#scroll-progress {
   144→  position: fixed;
   145→  top: 0;
   146→  left: 0;
   147→  height: 3px;
   148→  width: 0%;
   149→  background: linear-gradient(90deg, var(--color-primary), var(--color-accent));
   150→  z-index: 9999;

