   155→/* ---------- Utilities ---------- */
   156→.container {
   157→  max-width: 1100px;
   158→  margin: 0 auto;
   159→  padding: 0 28px;
   160→}
   161→
   162→.inline-link {
   163→  color: var(--color-primary);
   164→  font-weight: 500;
   165→  border-bottom: 1px solid transparent;
   166→  transition: border-color var(--transition);
   167→}
   168→.inline-link:hover { text-decoration: none; border-bottom-color: var(--color-primary); }
   169→
   170→/* ---------- Buttons ---------- */
   171→.btn {
   172→  display: inline-flex;
   173→  align-items: center;
   174→  gap: 7px;
   175→  padding: 10px 22px;
   176→  border-radius: var(--radius-full);
   177→  font-size: 0.875rem;
   178→  font-weight: 600;
   179→  font-family: var(--font-sans);
   180→  cursor: pointer;
   181→  transition: all var(--transition);
   182→  border: 2px solid transparent;
   183→  text-decoration: none !important;
   184→  white-space: nowrap;
   185→  letter-spacing: 0.01em;
   186→}
   187→.btn:hover { transform: translateY(-2px); text-decoration: none; }
   188→.btn:active { transform: translateY(0); }
   189→
   190→.btn-primary {
   191→  background: var(--color-primary);
   192→  color: #050c1a;
   193→  border-color: var(--color-primary);
   194→}
   195→[data-theme="light"] .btn-primary { color: #ffffff; }
   196→.btn-primary:hover { background: var(--color-primary-dark); border-color: var(--color-primary-dark); box-shadow: 0 4px 20px rgba(0, 200, 180, 0.35); }
   197→
   198→.btn-outline {
   199→  background: transparent;
   200→  color: var(--color-primary);
   201→  border-color: var(--color-primary);
   202→}
   203→.btn-outline:hover { background: var(--color-primary-light); }
   204→
   205→.btn-ghost {
   206→  background: var(--color-surface-2);
   207→  color: var(--color-text-muted);
   208→  border-color: var(--color-border);
   209→}
   210→.btn-ghost:hover { background: var(--color-surface-3); color: var(--color-text); }
   211→
   212→.btn-accent {
   213→  background: var(--color-accent);
   214→  color: #050c1a;
   215→  border-color: var(--color-accent);
   216→}
   217→[data-theme="light"] .btn-accent { color: #ffffff; }
   218→.btn-accent:hover { background: var(--color-accent-dark); border-color: var(--color-accent-dark); }
   219→
   220→.btn-sm {
   221→  padding: 6px 14px;
   222→  font-size: 0.8rem;
   223→}
   224→
   225→.btn-large {
   226→  padding: 13px 30px;
   227→  font-size: 0.95rem;
   228→}
   229→
   230→/* ---------- Sections ---------- */
   231→.section {
   232→  padding: 100px 0;
   233→}
   234→.section-alt {
   235→  background: var(--color-bg-alt);
   236→}
   237→
   238→.section-title {
   239→  font-family: var(--font-display);
   240→  font-size: clamp(1.8rem, 3vw, 2.6rem);
   241→  font-weight: 700;
   242→  color: var(--color-text);
   243→  margin-bottom: 12px;
   244→  letter-spacing: -0.01em;
   245→  line-height: 1.2;
   246→}
   247→.section-title::after {
   248→  content: '';
   249→  display: block;
   250→  width: 48px;
   251→  height: 3px;
   252→  background: linear-gradient(90deg, var(--color-primary), var(--color-accent));
   253→  margin-top: 12px;
   254→  border-radius: var(--radius-full);
   255→}
   256→
   257→.section-subtitle {
   258→  font-size: 1.05rem;
   259→  color: var(--color-text-muted);
   260→  margin-bottom: 56px;
   261→  max-width: 640px;
   262→  line-height: 1.65;
   263→}
   264→
   265→.subsection-title {
   266→  font-family: var(--font-display);
   267→  font-size: 1.4rem;
   268→  font-weight: 600;
   269→  color: var(--color-text);
   270→  margin: 64px 0 28px;
   271→}
   272→
   273→/* ---------- Fade-in animation ---------- */
   274→.fade-in {
   275→  opacity: 0;
   276→  transform: translateY(24px);
   277→  transition: opacity 0.55s ease, transform 0.55s ease;
   278→}
   279→.fade-in.visible {
   280→  opacity: 1;
   281→  transform: translateY(0);
   282→}
   283→
   284→/* =====================================================
   285→   NAVBAR
   286→   ===================================================== */
   287→.navbar {
   288→  position: fixed;
   289→  top: 0;
   290→  left: 0;
   291→  right: 0;
   292→  z-index: 1000;
   293→  height: var(--nav-height);
   294→  transition: background var(--transition), box-shadow var(--transition), backdrop-filter var(--transition);
   295→}
   296→.navbar.scrolled {
   297→  background: rgba(5, 12, 26, 0.85);
   298→  backdrop-filter: blur(16px);
   299→  -webkit-backdrop-filter: blur(16px);
   300→  box-shadow: 0 1px 0 var(--color-border), 0 4px 24px rgba(0,0,0,0.3);
   301→}
   302→[data-theme="light"] .navbar.scrolled {
   303→  background: rgba(248, 251, 255, 0.88);
   304→  box-shadow: 0 1px 0 var(--color-border), 0 4px 24px rgba(0,0,0,0.08);
   305→}
   306→
   307→.nav-container {
   308→  max-width: 1200px;
   309→  margin: 0 auto;
   310→  padding: 0 28px;
   311→  height: 100%;
