   415→/* =====================================================
   416→   HERO
   417→   ===================================================== */
   418→.hero {
   419→  position: relative;
   420→  min-height: 100vh;
   421→  display: flex;
   422→  align-items: center;
   423→  justify-content: center;
   424→  overflow: hidden;
   425→  background: linear-gradient(180deg, #020913 0%, #050c1a 30%, #070f20 60%, #0a1628 100%);
   426→  padding-top: var(--nav-height);
   427→}
   428→
   429→[data-theme="light"] .hero {
   430→  background: linear-gradient(180deg, #e8f1fd 0%, #d8eafa 30%, #cee3f8 60%, #c5dcf5 100%);
   431→}
   432→
   433→/* Aurora Background */
   434→.hero-aurora {
   435→  position: absolute;
   436→  inset: 0;
   437→  pointer-events: none;
   438→  overflow: hidden;
   439→}
   440→.aurora-1, .aurora-2, .aurora-3 {
   441→  position: absolute;
   442→  inset: -60%;
   443→  border-radius: 50%;
   444→}
   445→.aurora-1 {
   446→  background: radial-gradient(
   447→    ellipse 100% 50% at 25% 55%,
   448→    rgba(0, 200, 180, 0.22) 0%,
   449→    rgba(0, 150, 140, 0.08) 45%,
   450→    transparent 70%
   451→  );
   452→  animation: auroraFloat1 20s ease-in-out infinite alternate;
   453→}
   454→.aurora-2 {
   455→  background: radial-gradient(
   456→    ellipse 80% 60% at 70% 45%,
   457→    rgba(100, 30, 200, 0.18) 0%,
   458→    rgba(80, 20, 160, 0.07) 45%,
   459→    transparent 70%
   460→  );
   461→  animation: auroraFloat2 26s ease-in-out infinite alternate;
   462→}
   463→.aurora-3 {
   464→  background: radial-gradient(
   465→    ellipse 70% 80% at 50% 85%,
   466→    rgba(20, 60, 180, 0.15) 0%,
   467→    transparent 60%
   468→  );
   469→  animation: auroraFloat3 16s ease-in-out infinite alternate;
   470→}
   471→
   472→[data-theme="light"] .aurora-1 {
   473→  background: radial-gradient(
   474→    ellipse 100% 50% at 25% 55%,
   475→    rgba(0, 160, 145, 0.20) 0%,
   476→    rgba(0, 120, 110, 0.06) 45%,
   477→    transparent 70%
   478→  );
   479→}
   480→[data-theme="light"] .aurora-2 {
   481→  background: radial-gradient(
   482→    ellipse 80% 60% at 70% 45%,
   483→    rgba(90, 30, 180, 0.13) 0%,
   484→    transparent 70%
   485→  );
   486→}
   487→[data-theme="light"] .aurora-3 {
   488→  background: radial-gradient(
   489→    ellipse 70% 80% at 50% 85%,
   490→    rgba(10, 50, 160, 0.12) 0%,
   491→    transparent 60%
   492→  );
   493→}
   494→
   495→@keyframes auroraFloat1 {
   496→  from { transform: translate(0, 0) scale(1); }
   497→  to   { transform: translate(8%, -6%) scale(1.2); }
   498→}
   499→@keyframes auroraFloat2 {
   500→  from { transform: translate(0, 0) scale(1) rotate(0deg); }
   501→  to   { transform: translate(-7%, 9%) scale(1.18) rotate(-6deg); }
   502→}
   503→@keyframes auroraFloat3 {
   504→  from { transform: translate(0, 0) scale(1); }
   505→  to   { transform: translate(5%, 4%) scale(1.12); }
   506→}
   507→
   508→/* Hero star field */
   509→.hero-stars {
   510→  position: absolute;
   511→  inset: 0;
   512→  pointer-events: none;
   513→  background-image:
   514→    radial-gradient(1px 1px at 10% 15%, rgba(255,255,255,0.5) 0%, transparent 100%),
   515→    radial-gradient(1px 1px at 30% 8%, rgba(255,255,255,0.4) 0%, transparent 100%),
   516→    radial-gradient(1px 1px at 55% 22%, rgba(255,255,255,0.6) 0%, transparent 100%),
   517→    radial-gradient(1px 1px at 75% 5%, rgba(255,255,255,0.5) 0%, transparent 100%),
   518→    radial-gradient(1px 1px at 88% 18%, rgba(255,255,255,0.4) 0%, transparent 100%),
   519→    radial-gradient(1px 1px at 20% 40%, rgba(255,255,255,0.3) 0%, transparent 100%),
   520→    radial-gradient(1px 1px at 65% 35%, rgba(255,255,255,0.5) 0%, transparent 100%),
   521→    radial-gradient(1px 1px at 90% 45%, rgba(255,255,255,0.4) 0%, transparent 100%),
   522→    radial-gradient(1.5px 1.5px at 40% 60%, rgba(255,255,255,0.35) 0%, transparent 100%),
   523→    radial-gradient(1px 1px at 80% 72%, rgba(255,255,255,0.45) 0%, transparent 100%),
   524→    radial-gradient(1px 1px at 15% 78%, rgba(255,255,255,0.3) 0%, transparent 100%),
   525→    radial-gradient(1px 1px at 50% 88%, rgba(255,255,255,0.35) 0%, transparent 100%);
   526→}
   527→[data-theme="light"] .hero-stars { display: none; }
   528→
   529→.hero-content {
   530→  position: relative;
   531→  z-index: 1;
   532→  display: flex;
