     6→// ---------- Live Citation Count (Semantic Scholar API) ----------
     7→(function fetchLiveCitations() {
     8→  var url = 'https://api.semanticscholar.org/graph/v1/author/search' +
     9→    '?query=Getnet+Demil+Jenberia&fields=name,citationCount,paperCount,hIndex&limit=5';
    10→
    11→  fetch(url)
    12→    .then(function (r) { return r.json(); })
    13→    .then(function (data) {
    14→      if (!data.data || !data.data.length) return;
    15→
    16→      var best = null;
    17→      data.data.forEach(function (author) {
    18→        var name = (author.name || '').toLowerCase();
    19→        if (name.indexOf('getnet') === -1) return;
    20→        if (!best || (author.citationCount || 0) > (best.citationCount || 0)) {
    21→          best = author;
    22→        }
    23→      });
    24→      if (!best || !best.citationCount) return;
    25→
    26→      var citEl = document.querySelector('.metric-number[data-count]');
    27→      if (citEl) {
    28→        citEl.setAttribute('data-count', best.citationCount);
    29→        var subtitleEl = document.querySelector('#publications .section-subtitle');
    30→        if (subtitleEl) {
    31→          subtitleEl.innerHTML = subtitleEl.innerHTML.replace(
    32→            /\d+\+?\s*citations/i,
    33→            best.citationCount + '+ citations'
    34→          );
    35→        }
    36→      }
    37→    })
    38→    .catch(function () { /* keep static fallback */ });
    39→})();
