    48→if (themeToggle) {
    49→  themeToggle.addEventListener('click', function () {
    50→    var current = document.documentElement.getAttribute('data-theme');
    51→    var next = current === 'dark' ? 'light' : 'dark';
    52→    document.documentElement.setAttribute('data-theme', next);
