    57→// ---------- Scroll Progress Bar ----------
    58→var progressBar = document.getElementById('scroll-progress');
    59→function updateScrollProgress() {
    60→  if (!progressBar) return;
    61→  var scrollTop  = window.scrollY || document.documentElement.scrollTop;
    62→  var docHeight  = document.documentElement.scrollHeight - window.innerHeight;
    63→  var pct        = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;
    64→  progressBar.style.width = pct + '%';
