    98→// ---------- Active nav link on scroll ----------
    99→var sections = document.querySelectorAll('section[id]');
   100→var navItems = document.querySelectorAll('.nav-links a');
   101→
   102→function updateActiveNavLink() {
   103→  var scrollPos = window.scrollY + 120;
   104→  sections.forEach(function (section) {
   105→    if (
   106→      scrollPos >= section.offsetTop &&
   107→      scrollPos < section.offsetTop + section.offsetHeight
   108→    ) {
   109→      navItems.forEach(function (a) {
   110→        a.classList.remove('active');
   111→        if (a.getAttribute('href') === '#' + section.id) {
   112→          a.classList.add('active');
   113→        }
   114→      });
   115→    }
   116→  });
   117→}
   118→window.addEventListener('scroll', updateActiveNavLink, { passive: true });
   119→
   120→// ---------- Animated Counters ----------
   121→function animateCounter(el) {
   122→  var target   = parseInt(el.getAttribute('data-count'), 10);
   123→  var duration = 1400;
   124→  var start    = null;
   125→
   126→  function step(ts) {
   127→    if (!start) start = ts;
   128→    var progress = Math.min((ts - start) / duration, 1);
   129→    var eased = 1 - Math.pow(1 - progress, 3);
   130→    el.textContent = Math.round(eased * target);
   131→    if (progress < 1) requestAnimationFrame(step);
   132→  }
   133→  requestAnimationFrame(step);
   134→}
   135→
   136→var counterEls   = document.querySelectorAll('.metric-number[data-count]');
   137→var countersSeen = false;
   138→
   139→var counterObserver = new IntersectionObserver(function (entries) {
   140→  entries.forEach(function (entry) {
   141→    if (entry.isIntersecting && !countersSeen) {
   142→      countersSeen = true;
   143→      counterEls.forEach(animateCounter);
   144→      counterObserver.disconnect();
   145→    }
   146→  });
   147→}, { threshold: 0.3 });
   148→
   149→if (counterEls.length > 0) {
   150→  counterObserver.observe(counterEls[0].closest('.about-metrics') || counterEls[0]);
   151→}
   152→
   153→// ---------- Fade-in on scroll ----------
   154→var fadeEls = document.querySelectorAll(
   155→  '.highlight-card, .interest-card, .publication-card, .contact-card, ' +
   156→  '.project-card, .project-card-full, .news-card, .timeline-item, ' +
   157→  '.service-block, .skill-item'
   158→);
   159→
   160→var fadeObserver = new IntersectionObserver(function (entries) {
   161→  entries.forEach(function (entry) {
   162→    if (entry.isIntersecting) {
   163→      entry.target.classList.add('visible');
   164→      fadeObserver.unobserve(entry.target);
   165→    }
   166→  });
   167→}, { threshold: 0.08 });
   168→
   169→fadeEls.forEach(function (el) {
   170→  el.classList.add('fade-in');
   171→  fadeObserver.observe(el);
   172→});
   173→
   174→// ---------- Publication search ----------
   175→var pubSearch     = document.getElementById('pubSearch');
   176→var pubCards      = document.querySelectorAll('.publication-card');
   177→var pubYearGroups = document.querySelectorAll('.pub-year-group');
   178→var pubNoResults  = document.getElementById('pubNoResults');
   179→var activeFilter  = 'all';
   180→
   181→function filterPublications() {
   182→  var query   = pubSearch ? pubSearch.value.toLowerCase().trim() : '';
   183→  var visible = 0;
   184→
   185→  pubCards.forEach(function (card) {
   186→    var type     = (card.getAttribute('data-type') || '').toLowerCase();
   187→    var text     = card.textContent.toLowerCase();
   188→    var matchesQ = !query || text.indexOf(query) !== -1;
   189→    var matchesF = activeFilter === 'all' || type === activeFilter;
   190→
   191→    if (matchesQ && matchesF) {
   192→      card.style.display = '';
   193→      visible++;
   194→    } else {
   195→      card.style.display = 'none';
   196→    }
   197→  });
   198→
   199→  pubYearGroups.forEach(function (group) {
   200→    var cards      = group.querySelectorAll('.publication-card');
   201→    var anyVisible = false;
   202→    cards.forEach(function (c) { if (c.style.display !== 'none') anyVisible = true; });
   203→    group.style.display = anyVisible ? '' : 'none';
   204→  });
   205→
   206→  if (pubNoResults) {
   207→    pubNoResults.classList.toggle('visible', visible === 0);
   208→  }
   209→}
   210→
   211→if (pubSearch) {
   212→  pubSearch.addEventListener('input', filterPublications);
   213→}
   214→
   215→var filterBtns = document.querySelectorAll('.filter-btn');
   216→filterBtns.forEach(function (btn) {
   217→  btn.addEventListener('click', function () {
   218→    filterBtns.forEach(function (b) { b.classList.remove('active'); });
   219→    btn.classList.add('active');
   220→    activeFilter = btn.getAttribute('data-filter');
   221→    filterPublications();
   222→  });
   223→});
   224→
   225→// ---------- Footer year ----------
   226→var yearEl = document.getElementById('year');
   227→if (yearEl) {
   228→  yearEl.textContent = new Date().getFullYear();
   229→}
   230→
   231→// ---------- Nav brand: scroll to top, no hash in URL ----------
   232→var navBrand = document.querySelector('.nav-brand');
   233→if (navBrand) {
