## Decision 5: Medium RSS Integration — Exact Implementation

**Chosen service:** `rss2json.com` free tier (no key needed for public feeds, 1000 req/day limit — more than sufficient for a portfolio).

**Endpoint:** `https://api.rss2json.com/v1/api.json?rss_url=https://medium.com/feed/@getnetdemil&api_key=&count=10`

**Exact JS pattern** to add to `main.js`:

```javascript
// ---------- Medium RSS Feed (rss2json.com) ----------
(function initMediumFeed() {
  var feedContainer = document.getElementById('mediumFeed');
  if (!feedContainer) return;

  var RSS_URL = 'https://medium.com/feed/@getnetdemil';
  var API_URL = 'https://api.rss2json.com/v1/api.json?rss_url='
              + encodeURIComponent(RSS_URL) + '&count=10';

  function truncate(str, max) {
    // Strip HTML tags first
    var plain = str.replace(/<[^>]+>/g, '');
    return plain.length > max ? plain.slice(0, max).trimEnd() + '…' : plain;
  }

  function formatDate(dateStr) {
    var d = new Date(dateStr);
    if (isNaN(d)) return '';
    return d.toLocaleDateString('en-GB', { month: 'short', year: 'numeric' });
  }

  function estimateReadTime(content) {
    var words = content.replace(/<[^>]+>/g, '').split(/\s+/).length;
    return Math.max(1, Math.round(words / 200)) + ' min read';
  }

  function renderPosts(posts) {
    if (!posts || !posts.length) {
      feedContainer.innerHTML =
        '<p class="medium-empty">No posts found. ' +
        '<a href="https://medium.com/@getnetdemil" target="_blank" rel="noopener noreferrer">' +
        'Visit Medium profile →</a></p>';
      return;
    }

    var badge = document.getElementById('mediumBadge');
    if (badge) badge.textContent = posts.length;

    var html = posts.map(function (post) {
      return '<article class="medium-card">' +
        '<div class="medium-card-meta">' +
          '<time class="medium-date">' + formatDate(post.pubDate) + '</time>' +
          '<span class="medium-read">' + estimateReadTime(post.content || post.description) + '</span>' +
        '</div>' +
        '<h3 class="medium-title">' +
          '<a href="' + post.link + '" target="_blank" rel="noopener noreferrer">' +
          post.title + '</a>' +
        '</h3>' +
        '<p class="medium-excerpt">' + truncate(post.description, 140) + '</p>' +
        '<a class="medium-read-link" href="' + post.link + '" ' +
           'target="_blank" rel="noopener noreferrer">Read on Medium →</a>' +
      '</article>';
    }).join('');

    feedContainer.innerHTML = html;

    // Add LinkedIn CTA card at the end
    feedContainer.insertAdjacentHTML('beforeend',
      '<div class="medium-card medium-card--linkedin">' +
        '<div class="medium-card-meta"><span class="medium-read">Professional updates</span></div>' +
        '<h3 class="medium-title">Follow on LinkedIn</h3>' +
        '<p class="medium-excerpt">Research updates, conference posts, and collaboration opportunities.</p>' +
        '<a class="medium-read-link" href="https://www.linkedin.com/in/getnetdemil/" ' +
           'target="_blank" rel="noopener noreferrer">View LinkedIn Profile →</a>' +
      '</div>'
    );
  }

  fetch(API_URL)
    .then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    })
    .then(function (data) {
      if (data.status === 'ok' && data.items) {
        renderPosts(data.items);
      } else {
        throw new Error('Bad response');
      }
    })
    .catch(function () {
      feedContainer.innerHTML =
        '<p class="medium-empty">Could not load posts. ' +
        '<a href="https://medium.com/@getnetdemil" target="_blank" rel="noopener noreferrer">' +
        'Read on Medium →</a></p>';
    });
})();
```

**Tab switching JS** (also in `main.js`):

```javascript
// ---------- News Tabs ----------
(function initNewsTabs() {
  var tabs   = document.querySelectorAll('.news-tab');
  var panels = document.querySelectorAll('[role="tabpanel"]');

  tabs.forEach(function (tab) {
    tab.addEventListener('click', function () {
      var target = tab.getAttribute('data-tab');

      tabs.forEach(function (t) {
        t.classList.remove('active');
        t.setAttribute('aria-selected', 'false');
      });
      tab.classList.add('active');
      tab.setAttribute('aria-selected', 'true');

      panels.forEach(function (panel) {
        var isTarget = panel.id === 'tab-' + target;
        panel.hidden = !isTarget;
      });
    });
  });
})();
```

